head.script:
scwin.screenId = "uldmgt50600";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("keyword"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.list();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50600.onpageload' }); }
};

// [A] 초기 목록 미해결 — uldmgt50600: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50600.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.form_2_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.form_2_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin form_2_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50600.form_2_onsubmit' }); }
};

/**
 * @event
 * @name scwin.ipt_keyword_onkeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_keyword_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.onEnter()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50600.ipt_keyword_onkeyup' }); }
};

/**
 * @event
 * @name scwin.img_98_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_98_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_98_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50600.img_98_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_list_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_list_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr", unresolved: "action:self_submit:tx_list_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_replaceFormForm_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_replaceFormForm_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_replaceFormForm_xhr", unresolved: "action:self_submit:tx_fn_replaceFormForm_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_restoreFormForm_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_restoreFormForm_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_restoreFormForm_xhr", unresolved: "action:self_submit:tx_fn_restoreFormForm_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin list — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent('dma_listXhrReq').set('method', "findEmergencyFormList");
    await scwin.tx_list_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setValue) ? $c.util.getComponent('formListDiv').setValue(responseText) : (($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setText) ? $c.util.getComponent('formListDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'formListDiv'), void (responseText)));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param orderBy
 * @returns
 * @hidden N
*/
scwin.search = async function (orderBy) {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (orderBy != null) {
        const prevOrderBy = $c.util.getComponent('dma_listXhrReq').get('orderBy');
        $c.util.getComponent('dma_listXhrReq').set('orderBy', orderBy);
        if (prevOrderBy === orderBy) {
            const ascDiv = $c.util.getComponent('dma_listXhrReq').get('ascDiv');
            if (ascDiv === "asc") {
                $c.util.getComponent('dma_listXhrReq').set('ascDiv', "desc");
            } else {
                $c.util.getComponent('dma_listXhrReq').set('ascDiv', "asc");
            }
        } else {
            $c.util.getComponent('dma_listXhrReq').set('ascDiv', "asc");
        }
    } else {
        $c.util.getComponent('dma_listXhrReq').set('ascDiv', "asc");
    }
    $c.util.getComponent('dma_listXhrReq').set('pageIndex', 1);
    await scwin.list();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onEnter
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onEnter = async function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.search();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.replaceFormForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formKorNm
 * @returns
 * @hidden N
*/
scwin.replaceFormForm = async function (formCd, formKorNm) {
    /* sdd-asis-lifecycle:begin fn_replaceFormForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("[" + formKorNm + "] 서식의 종목명을 수정가능하게 변경하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_listXhrReq').set('formCd', formCd);
    scwin.form_listForm.action = "/filing/updateForm.do";
    $c.util.getComponent('dma_listXhrReq').set('method', "replaceFormForm");
    await scwin.tx_fn_replaceFormForm_xhr();
    $c.win.setPageFrameSrc($c.win.getFrame(), null);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.restoreFormForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formKorNm
 * @returns
 * @hidden N
*/
scwin.restoreFormForm = async function (formCd, formKorNm) {
    /* sdd-asis-lifecycle:begin fn_restoreFormForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("[" + formKorNm + "] 서식의 종목명 수정을 못하게 변경하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_listXhrReq').set('formCd', formCd);
    scwin.form_listForm.action = "/filing/updateForm.do";
    $c.util.getComponent('dma_listXhrReq').set('method', "restoreFormForm");
    await scwin.tx_fn_restoreFormForm_xhr();
    $c.win.setPageFrameSrc($c.win.getFrame(), null);
    /* sdd-asis-lifecycle:end */
};
